from typing import List

class Solution:
    def removeElement(self, nums: List[int], val: int) -> int:
        i, n = 0, len(nums)
        while i < n:
            if nums[i] == val:
                nums[i] = nums[n - 1]
                n -= 1
                # Do not increment i; the swapped value must be checked.
            else:
                i += 1
        return n

